1919	+func normalizeLanguages(languages []string) []string {
1920	+	if len(languages) == 0 {
1921	+		return nil
1922	+	}
1923	+
1924	+	normalized := make([]string, 0, len(languages))
1925	+	seen := make(map[string]struct{}, len(languages))
1926	+
1927	+	for _, language := range languages {
1928	+		language = strings.ToLower(strings.TrimSpace(language))
1929	+		if language == "" {
1930	+			continue
1931	+		}
1932	+		if _, ok := seen[language]; ok {
1933	+			continue
1934	+		}
1935	+		seen[language] = struct{}{}
1936	+		normalized = append(normalized, language)
1937	+	}
1938	+
1939	+	return normalized
