1942	+func languageMatches(trackLanguage string, preferredLanguage string) bool {
1943	+	trackLanguage = strings.ToLower(strings.TrimSpace(trackLanguage))
1944	+	preferredLanguage = strings.ToLower(strings.TrimSpace(preferredLanguage))
1945	+
1946	+	if trackLanguage == preferredLanguage {
1947	+		return true
1948	+	}
1949	+	if strings.HasPrefix(trackLanguage, preferredLanguage+"-") {
1950	+		return true
1951	+	}
1952	+	if strings.HasPrefix(preferredLanguage, trackLanguage+"-") {
1953	+		return true
1954	+	}
1955	+
1956	+	return false
1957	+}
