1959	+func formatTranscriptMarkdown(transcript []transcriptSegment) string {
1960	+	var builder strings.Builder
1961	+	wroteSegment := false
1962	+
1963	+	for _, segment := range transcript {
1964	+		text := normalizeTranscriptText(segment.Text)
1965	+		if text == "" {
1966	+			continue
1967	+		}
1968	+
1969	+		if wroteSegment {
1970	+			builder.WriteString("\n\n")
1971	+		}
1972	+		builder.WriteString("## ")
1973	+		builder.WriteString(formatTimestamp(segment.StartMs))
1974	+		builder.WriteString("\n")
1975	+		builder.WriteString(text)
1976	+		wroteSegment = true
1977	+	}
1978	+
1979	+	return builder.String()
1980	+}
1981	+
1982	+func normalizeTranscriptText(text string) string {
1983	+	words := strings.Fields(text)
1984	+	return strings.TrimSpace(strings.Join(words, " "))
1985	+}
