1987	+func formatTimestamp(startMs int) string {
1988	+	if startMs < 0 {
1989	+		startMs = 0
1990	+	}
1991	+
1992	+	totalSeconds := startMs / 1000
1993	+	hours := totalSeconds / 3600
1994	+	minutes := (totalSeconds % 3600) / 60
1995	+	seconds := totalSeconds % 60
1996	+
1997	+	if hours > 0 {
1998	+		return fmt.Sprintf("%02d:%02d:%02d", hours, minutes, seconds)
1999	+	}
2000	+
2001	+	return fmt.Sprintf("%02d:%02d", minutes, seconds)
2002	+}
