233		}
234		duration, err := time.ParseDuration(backoff)
235		if err != nil {
236			return 0, fmt.Errorf("retry_backoff must be a Go duration: %q", value)
237		}
238		if duration < 0 {
239			return 0, fmt.Errorf("retry_backoff cannot be negative: %q", value)
240		}
241		return duration, nil
