281	func (extractor *Extractor) extractWithYTDLPBackend(
282		ctx context.Context,
283		parsed ParsedURL,
284		options ExtractOptions,
285	) (*Result, error) {
286		policy := normalizeTranscriptionPolicy(options)
287		info, err := extractor.ytDLP.loadInfo(ctx, parsed.CanonicalURL)
288		if err != nil {
289			if isContextError(err) {
290				return nil, err
291			}
292			return nil, fmt.Errorf("yt-dlp backend: %w", err)
293		}
294	
295		result := &Result{
296			Metadata:            metadataFromYTDLPInfo(parsed, info),
297			TranscriptionPolicy: policy,
298		}
299		if policy == TranscriptionPolicySTT {
300			return extractor.extractSTTFromYTDLP(ctx, parsed, info, result, nil)
301		}
302	
303		allowAutomaticCaptions := policy == TranscriptionPolicyCaptions
304		captionResult, err := extractor.ytDLP.extractCaptionsFromInfo(
305			ctx,
306			parsed,
307			info,
308			options.PreferredLanguages,
309			allowAutomaticCaptions,
310			options.AllowTranslatedCaptions,
311		)
312		if err == nil {
313			captionResult.TranscriptionPolicy = policy
314			return captionResult, nil
315		}
316		if captionResult != nil {
317			result = captionResult
318			result.TranscriptionPolicy = policy
319		}
320		if isContextError(err) {
321			return result, err
322		}
323		if isTranscriptUnavailable(err) && policy == TranscriptionPolicyAuto {
324			return extractor.extractSTTFromYTDLP(ctx, parsed, info, result, err)
325		}
326		return result, err
327	}
