437		}
438	
439		normalized := make([]string, 0, len(languages))
440		seen := make(map[string]struct{}, len(languages))
441	
442		for _, language := range languages {
443			language = strings.ToLower(strings.TrimSpace(language))
444			if language == "" {
445				continue
446			}
447			if _, ok := seen[language]; ok {
448				continue
449			}
450			seen[language] = struct{}{}
451			normalized = append(normalized, language)
452		}
