502	func formatTimestamp(startMs int) string {
503		if startMs < 0 {
504			startMs = 0
505		}
506	
507		totalSeconds := startMs / 1000
508		hours := totalSeconds / 3600
509		minutes := (totalSeconds % 3600) / 60
510		seconds := totalSeconds % 60
511	
512		if hours > 0 {
513			return fmt.Sprintf("%02d:%02d:%02d", hours, minutes, seconds)
514		}
515	
516		return fmt.Sprintf("%02d:%02d", minutes, seconds)
517	}
