144	func (backend *ytDLPBackend) ExtractCaptions(
145		ctx context.Context,
146		parsed ParsedURL,
147		preferredLanguages []string,
148		allowAutomatic bool,
149		allowTranslated bool,
150	) (*Result, error) {
151		if backend == nil {
152			return nil, fmt.Errorf("%w: backend is nil", errYTDLPUnavailable)
153		}
154		if ctx == nil {
155			ctx = context.Background()
156		}
157	
158		info, err := backend.loadInfo(ctx, parsed.CanonicalURL)
159		if err != nil {
160			return nil, err
161		}
162	
163		return backend.extractCaptionsFromInfo(ctx, parsed, info, preferredLanguages, allowAutomatic, allowTranslated)
164	}
