166	func (backend *ytDLPBackend) extractCaptionsFromInfo(
167		ctx context.Context,
168		parsed ParsedURL,
169		info ytDLPInfo,
170		preferredLanguages []string,
171		allowAutomatic bool,
172		allowTranslated bool,
173	) (*Result, error) {
174		result := &Result{Metadata: metadataFromYTDLPInfo(parsed, info)}
175		candidate, ok := selectYTDLPCaption(info, preferredLanguages, allowAutomatic, allowTranslated)
176		if !ok {
177			return result, &Error{
178				Kind:    ErrorKindTranscriptUnavailable,
179				URL:     parsed.CanonicalURL,
180				VideoID: parsed.VideoID,
181				Message: ytDLPCaptionUnavailableMessage(preferredLanguages, allowTranslated),
182				Err:     errTranscriptDisabled,
183			}
184		}
185	
186		markdown, err := backend.downloadCaption(ctx, parsed.CanonicalURL, candidate)
187		if err != nil {
188			return result, err
189		}
190		if strings.TrimSpace(markdown) == "" {
191			return result, fmt.Errorf("%w: empty transcript for %q", errYTDLPCaptionFetchFailed, candidate.Language)
192		}
193	
194		result.Markdown = markdown
195		result.Source = TranscriptSourceCaptions
196		result.Language = candidate.Language
197		if candidate.Automatic {
198			result.CaptionKind = CaptionKindAutomatic
199		} else {
200			result.CaptionKind = CaptionKindManual
201		}
202		return result, nil
203	}
