205	func (backend *ytDLPBackend) loadInfo(ctx context.Context, rawURL string) (ytDLPInfo, error) {
206		stdout, _, err := backend.run(ctx, "metadata", append(backend.baseArgs(),
207			"--dump-single-json",
208			"--skip-download",
209			rawURL,
210		)...)
211		if err != nil {
212			return ytDLPInfo{}, backend.wrapMetadataFetchError(err)
213		}
214	
215		var info ytDLPInfo
216		if err := json.Unmarshal([]byte(stdout), &info); err != nil {
217			return ytDLPInfo{}, fmt.Errorf("yt-dlp metadata: parse JSON: %w", err)
218		}
219		return info, nil
220	}
