222	// ListPlaylistEntries resolves the raw entries for a channel or playlist URL. A
223	// limit greater than zero caps the result to the newest uploads. Callers apply
224	// platform-specific filtering and URL canonicalization on the returned entries.
225	func (backend *ytDLPBackend) ListPlaylistEntries(ctx context.Context, channelURL string, limit int) ([]PlaylistEntry, error) {
226		if backend == nil {
227			return nil, fmt.Errorf("%w: backend is nil", errYTDLPUnavailable)
228		}
229		if ctx == nil {
230			ctx = context.Background()
231		}
232	
233		args := append(backend.playlistArgs(),
234			"--flat-playlist",
235			"--dump-single-json",
236			"--skip-download",
237		)
238		if limit > 0 {
239			args = append(args, "--playlist-end", strconv.Itoa(limit))
240		}
241		args = append(args, channelURL)
242	
243		stdout, _, err := backend.run(ctx, "channel", args...)
244		if err != nil {
245			return nil, backend.wrapMetadataFetchError(err)
246		}
247	
248		var playlist ytDLPPlaylist
249		if err := json.Unmarshal([]byte(stdout), &playlist); err != nil {
250			return nil, fmt.Errorf("yt-dlp channel: parse JSON: %w", err)
251		}
252	
253		entries := make([]PlaylistEntry, 0, len(playlist.Entries))
254		for _, entry := range playlist.Entries {
255			entries = append(entries, PlaylistEntry{
256				ID:         strings.TrimSpace(entry.ID),
257				Title:      strings.TrimSpace(entry.Title),
258				URL:        strings.TrimSpace(entry.URL),
259				WebpageURL: strings.TrimSpace(entry.WebpageURL),
260			})
261		}
262		return entries, nil
263	}
