265	func (backend *ytDLPBackend) downloadCaption(
266		ctx context.Context,
267		rawURL string,
268		candidate ytDLPCaptionCandidate,
269	) (string, error) {
270		tempDir, err := os.MkdirTemp("", "kb-ytdlp-*")
271		if err != nil {
272			return "", fmt.Errorf("yt-dlp captions: create temp dir: %w", err)
273		}
274		defer func() {
275			_ = os.RemoveAll(tempDir)
276		}()
277	
278		args := append(backend.baseArgs(),
279			"--skip-download",
280			"--sub-langs", candidate.Language,
281			"--sub-format", "json3/vtt/best",
282			"--paths", "home:"+tempDir,
283			"--output", "%(id)s.%(ext)s",
284		)
285		if candidate.Automatic {
286			args = append(args, "--write-auto-subs")
287		} else {
288			args = append(args, "--write-subs")
289		}
290		args = append(args, rawURL)
291	
292		if _, _, err := backend.run(ctx, "captions", args...); err != nil {
293			return "", backend.wrapCaptionFetchError(err, candidate.Language)
294		}
295	
296		data, ext, err := readYTDLPSubtitleFile(tempDir)
297		if err != nil {
298			return "", backend.wrapCaptionFetchError(err, candidate.Language)
299		}
300		switch ext {
301		case ".json3":
302			markdown, err := formatYTDLPJSON3Transcript(data)
303			if err != nil {
304				return "", backend.wrapCaptionFetchError(err, candidate.Language)
305			}
306			return markdown, nil
307		case ".vtt":
308			markdown, err := formatYTDLPVTTTranscript(data)
309			if err != nil {
310				return "", backend.wrapCaptionFetchError(err, candidate.Language)
311			}
312			return markdown, nil
313		default:
314			return "", backend.wrapCaptionFetchError(
315				fmt.Errorf("yt-dlp captions: unsupported subtitle extension %q", ext),
316				candidate.Language,
317			)
318		}
319	}
