321	func (backend *ytDLPBackend) downloadAudio(
322		ctx context.Context,
323		rawURL string,
324		format string,
325	) (ytDLPDownloadedAudio, error) {
326		if backend == nil {
327			return ytDLPDownloadedAudio{}, fmt.Errorf("%w: backend is nil", errYTDLPUnavailable)
328		}
329		if ctx == nil {
330			ctx = context.Background()
331		}
332		format = strings.TrimSpace(strings.ToLower(format))
333		if format == "" {
334			format = "mp3"
335		}
336		tempDir, err := os.MkdirTemp("", "kb-ytdlp-audio-*")
337		if err != nil {
338			return ytDLPDownloadedAudio{}, fmt.Errorf("yt-dlp audio: create temp dir: %w", err)
339		}
340		cleanup := func() {
341			_ = os.RemoveAll(tempDir)
342		}
343	
344		args := append(backend.baseArgs(),
345			"--extract-audio",
346			"--audio-format", format,
347			"--paths", "home:"+tempDir,
348			"--output", "%(id)s.%(ext)s",
349			rawURL,
350		)
351		if _, _, err := backend.run(ctx, "audio", args...); err != nil {
352			cleanup()
353			return ytDLPDownloadedAudio{}, backend.wrapAudioFetchError(err)
354		}
355	
356		path, detectedFormat, err := findYTDLPAudioFile(tempDir)
357		if err != nil {
358			cleanup()
359			return ytDLPDownloadedAudio{}, backend.wrapAudioFetchError(err)
360		}
361		return ytDLPDownloadedAudio{Path: path, Format: detectedFormat, cleanup: cleanup}, nil
362	}
