377	func (backend *ytDLPBackend) wrapAudioFetchError(err error) error {
378		if err == nil {
379			return nil
380		}
381		if isYTDLPRateLimitedError(err) {
382			return newRateLimitedError(
383				"",
384				"audio download was rate limited through yt-dlp; "+backend.networkBlockHint(),
385				err,
386			)
387		}
388		if isYTDLPNetworkBlockedError(err) {
389			return newNetworkBlockedError(
390				"",
391				"audio download was blocked through yt-dlp; "+backend.networkBlockHint(),
392				err,
393			)
394		}
395		return fmt.Errorf("yt-dlp audio: %w", err)
396	}
