398	func findYTDLPAudioFile(directory string) (string, string, error) {
399		entries, err := os.ReadDir(directory)
400		if err != nil {
401			return "", "", fmt.Errorf("read audio output directory: %w", err)
402		}
403		for _, entry := range entries {
404			if entry.IsDir() {
405				continue
406			}
407			ext := strings.TrimPrefix(strings.ToLower(filepath.Ext(entry.Name())), ".")
408			if ext == "" {
409				continue
410			}
411			switch ext {
412			case "mp3", "mp4", "mpeg", "mpga", "m4a", "wav", "webm":
413				return filepath.Join(directory, entry.Name()), ext, nil
414			}
415		}
416		return "", "", errors.New("yt-dlp audio: no audio file was produced")
417	}
