419	func (backend *ytDLPBackend) wrapMetadataFetchError(err error) error {
420		if err == nil {
421			return nil
422		}
423		if isYTDLPRateLimitedError(err) {
424			return newRateLimitedError("", "metadata request was rate limited through yt-dlp; "+backend.networkBlockHint(), err)
425		}
426		if isYTDLPNetworkBlockedError(err) {
427			return newNetworkBlockedError("", "metadata request was blocked through yt-dlp; "+backend.networkBlockHint(), err)
428		}
429		return err
430	}
