432	func (backend *ytDLPBackend) wrapCaptionFetchError(err error, language string) error {
433		if err == nil {
434			return nil
435		}
436		if errors.Is(err, errYTDLPCaptionFetchFailed) {
437			return err
438		}
439		if isYTDLPRateLimitedError(err) {
440			return fmt.Errorf("%w: %w", errYTDLPCaptionFetchFailed, newRateLimitedError(
441				"",
442				fmt.Sprintf("caption language %q was rate limited through yt-dlp; %s", language, backend.networkBlockHint()),
443				err,
444			))
445		}
446		if isYTDLPNetworkBlockedError(err) {
447			return fmt.Errorf("%w: %w", errYTDLPCaptionFetchFailed, newNetworkBlockedError(
448				"",
449				"captions request was blocked through yt-dlp; "+backend.networkBlockHint(),
450				err,
451			))
452		}
453		return fmt.Errorf("%w: %w", errYTDLPCaptionFetchFailed, err)
454	}
