469	func (backend *ytDLPBackend) commonArgs(allowPlaylist bool) []string {
470		args := []string{"--ignore-config"}
471		if !allowPlaylist {
472			args = append(args, "--no-playlist")
473		}
474		args = append(args,
475			"--retries", strconv.Itoa(normalizedRetryAttempts(backend.retry)),
476			"--fragment-retries", strconv.Itoa(normalizedRetryAttempts(backend.retry)),
477		)
478		if sleep := normalizedRetrySleep(backend.retry); sleep != "" {
479			args = append(args, "--retry-sleep", sleep)
480		}
481		if proxy := strings.TrimSpace(backend.cfg.Proxy); proxy != "" {
482			args = append(args, "--proxy", proxy)
483		}
484		if cookiesFile := strings.TrimSpace(backend.cfg.CookiesFile); cookiesFile != "" {
485			args = append(args, "--cookies", cookiesFile)
486		}
487		if userAgent := strings.TrimSpace(backend.cfg.UserAgent); userAgent != "" {
488			args = append(args, "--user-agent", userAgent)
489		}
490		return args
491	}
