493	func (backend *ytDLPBackend) run(ctx context.Context, label string, args ...string) (string, string, error) {
494		binaryPath, err := backend.resolveBinary()
495		if err != nil {
496			return "", "", err
497		}
498	
499		command := backend.commandContext(ctx, binaryPath, args...)
500		var stdout bytes.Buffer
501		var stderr bytes.Buffer
502		command.Stdout = &stdout
503		command.Stderr = &stderr
504		err = command.Run()
505		stdoutText := strings.TrimSpace(stdout.String())
506		stderrText := strings.TrimSpace(stderr.String())
507		if err != nil {
508			if ctxErr := ctx.Err(); ctxErr != nil {
509				return stdoutText, stderrText, fmt.Errorf("yt-dlp %s: %w", label, ctxErr)
510			}
511			diagnostics := cleanYTDLPDiagnostics(stderrText)
512			if diagnostics == "" {
513				diagnostics = cleanYTDLPDiagnostics(stdoutText)
514			}
515			if diagnostics != "" {
516				return stdoutText, stderrText, fmt.Errorf("yt-dlp %s: %w: %s", label, err, diagnostics)
517			}
518			return stdoutText, stderrText, fmt.Errorf("yt-dlp %s: %w", label, err)
519		}
520		return stdoutText, stderrText, nil
521	}
522	
523	func (backend *ytDLPBackend) resolveBinary() (string, error) {
524		binaryPath := strings.TrimSpace(backend.binaryPath)
525		if binaryPath == "" {
526			binaryPath = ytdlpDefaultBinary
527		}
528	
529		resolvedPath, err := backend.lookPath(binaryPath)
530		if err != nil {
531			if errors.Is(err, exec.ErrNotFound) || errors.Is(err, os.ErrNotExist) {
532				return "", fmt.Errorf("%w: install yt-dlp or configure yt_dlp_path: %w", errYTDLPUnavailable, err)
533			}
534			return "", fmt.Errorf("resolve yt-dlp binary %q: %w", binaryPath, err)
535		}
536		return resolvedPath, nil
537	}
