539	func normalizedRetryAttempts(retry retryPolicy) int {
540		if retry.Attempts < 1 {
541			return 1
542		}
543		return retry.Attempts
544	}
545	
546	func normalizedRetrySleep(retry retryPolicy) string {
547		if retry.Backoff <= 0 {
548			return ""
549		}
550		return strconv.FormatFloat(retry.Backoff.Seconds(), 'f', -1, 64)
551	}
552	
553	func cleanYTDLPDiagnostics(text string) string {
554		lines := strings.Split(strings.TrimSpace(text), "\n")
555		cleaned := make([]string, 0, len(lines))
556		for _, line := range lines {
557			line = strings.TrimSpace(line)
558			if line == "" {
559				continue
560			}
561			cleaned = append(cleaned, line)
562		}
563		return strings.Join(cleaned, "; ")
564	}
565	
566	func isYTDLPRateLimitedError(err error) bool {
567		if err == nil {
568			return false
569		}
570		message := strings.ToLower(err.Error())
571		for _, marker := range []string{
572			"http error 429",
573			"too many requests",
574			"unexpected status code: 429",
575		} {
576			if strings.Contains(message, marker) {
577				return true
578			}
579		}
580		return false
581	}
582	
583	func isYTDLPNetworkBlockedError(err error) bool {
584		if err == nil {
585			return false
586		}
587		message := strings.ToLower(err.Error())
588		for _, marker := range []string{
589			"http error 400",
590			"http error 403",
591			"http error 500",
592			"http error 502",
593			"http error 503",
594			"http error 504",
595			"bot",
596			"sign in to confirm",
597			"not a bot",
598		} {
599			if strings.Contains(message, marker) {
600				return true
601			}
602		}
603		return false
604	}
