606	func metadataFromYTDLPInfo(parsed ParsedURL, info ytDLPInfo) Metadata {
607		videoID := strings.TrimSpace(info.ID)
608		if videoID == "" {
609			videoID = parsed.VideoID
610		}
611		videoURL := strings.TrimSpace(info.WebpageURL)
612		if videoURL == "" {
613			videoURL = parsed.CanonicalURL
614		}
615		channel := strings.TrimSpace(info.Channel)
616		if channel == "" {
617			channel = strings.TrimSpace(info.Uploader)
618		}
619		duration := durationFromYTDLPSeconds(info.Duration)
620		return Metadata{
621			VideoID:              videoID,
622			URL:                  videoURL,
623			Title:                strings.TrimSpace(info.Title),
624			Description:          strings.TrimSpace(info.Description),
625			Channel:              channel,
626			ChannelID:            strings.TrimSpace(info.ChannelID),
627			UploaderID:           strings.TrimSpace(info.UploaderID),
628			Duration:             duration,
629			DurationString:       durationStringFromYTDLP(info.DurationString, duration),
630			PublishDate:          parseYTDLPUploadDate(info.UploadDate),
631			ViewCount:            cloneInt64(info.ViewCount),
632			LikeCount:            cloneInt64(info.LikeCount),
633			CommentCount:         cloneInt64(info.CommentCount),
634			ChannelFollowerCount: cloneInt64(info.ChannelFollowerCount),
635			Categories:           normalizeYTDLPStringSlice(info.Categories),
636			VideoTags:            normalizeYTDLPStringSlice(info.Tags),
637			Language:             strings.TrimSpace(info.Language),
638			LiveStatus:           strings.TrimSpace(info.LiveStatus),
639			WasLive:              cloneBool(info.WasLive),
640			ChapterCount:         len(info.Chapters),
641		}
642	}
643	
644	func durationFromYTDLPSeconds(seconds float64) time.Duration {
645		if seconds <= 0 || math.IsNaN(seconds) || math.IsInf(seconds, 0) {
646			return 0
647		}
648		return time.Duration(seconds * float64(time.Second))
649	}
650	
651	func parseYTDLPUploadDate(value string) time.Time {
652		parsed, err := time.Parse("20060102", strings.TrimSpace(value))
653		if err != nil {
654			return time.Time{}
655		}
656		return parsed.UTC()
657	}
658	
659	func durationStringFromYTDLP(value string, duration time.Duration) string {
660		if trimmed := strings.TrimSpace(value); trimmed != "" {
661			return trimmed
662		}
663		if duration <= 0 {
664			return ""
665		}
666		totalSeconds := int64(duration / time.Second)
667		hours := totalSeconds / 3600
668		minutes := (totalSeconds % 3600) / 60
669		seconds := totalSeconds % 60
670		if hours > 0 {
671			return fmt.Sprintf("%d:%02d:%02d", hours, minutes, seconds)
672		}
673		return fmt.Sprintf("%d:%02d", minutes, seconds)
674	}
675	
676	func cloneInt64(value *int64) *int64 {
677		if value == nil {
678			return nil
679		}
680		cloned := *value
681		return &cloned
682	}
683	
684	func cloneBool(value *bool) *bool {
685		if value == nil {
686			return nil
687		}
688		cloned := *value
689		return &cloned
690	}
