831	func ytDLPCaptionLess(left ytDLPCaptionCandidate, right ytDLPCaptionCandidate, preferredLanguage string) bool {
832		leftRank := ytDLPCaptionRank(left, preferredLanguage)
833		rightRank := ytDLPCaptionRank(right, preferredLanguage)
834		if leftRank != rightRank {
835			return leftRank < rightRank
836		}
837		if left.Original && right.Original {
838			leftEnglish := 1
839			if languageMatches(left.BaseLanguage, "en") {
840				leftEnglish = 0
841			}
842			rightEnglish := 1
843			if languageMatches(right.BaseLanguage, "en") {
844				rightEnglish = 0
845			}
846			if leftEnglish != rightEnglish {
847				return leftEnglish < rightEnglish
848			}
849		}
850		return left.Language < right.Language
