853	func ytDLPCaptionRank(candidate ytDLPCaptionCandidate, preferredLanguage string) int {
854		if preferredLanguage == "orig" {
855			if !candidate.Automatic {
856				return 0
857			}
858			switch {
859			case candidate.OriginalKey:
860				return 1
861			case captionLanguageExactMatch(candidate.Language, candidate.BaseLanguage):
862				return 2
863			default:
864				return 3
865			}
866		}
867	
868		matchRank := 2
869		switch {
870		case captionLanguageExactMatch(candidate.Language, preferredLanguage):
871			matchRank = 0
872		case candidate.BaseLanguage == preferredLanguage:
873			matchRank = 1
874		}
875		automaticRank := 0
876		if candidate.Automatic {
877			automaticRank = 1
878		}
879		translatedRank := 0
880		if candidate.Translated {
881			translatedRank = 1
882		}
883		return matchRank*10 + automaticRank*2 + translatedRank
884	}
