995			}
996			textLines := make([]string, 0, 2)
997			for index++; index < len(lines); index++ {
998				textLine := strings.TrimSpace(lines[index])
999				if textLine == "" {
1000					break
1001				}
1002				textLines = append(textLines, textLine)
1003			}
1004			text := normalizeTranscriptText(strings.Join(textLines, " "))
1005			if text == "" {
