1013	func parseVTTTimestampMs(value string) (int, bool) {
1014		value = strings.TrimSpace(value)
1015		parts := strings.Split(value, ":")
1016		if len(parts) < 2 || len(parts) > 3 {
1017			return 0, false
1018		}
1019	
1020		secondsPart := parts[len(parts)-1]
1021		seconds, err := strconv.ParseFloat(strings.Replace(secondsPart, ",", ".", 1), 64)
1022		if err != nil {
1023			return 0, false
1024		}
1025		minutes, err := strconv.Atoi(parts[len(parts)-2])
1026		if err != nil {
1027			return 0, false
1028		}
1029		hours := 0
1030		if len(parts) == 3 {
1031			hours, err = strconv.Atoi(parts[0])
1032			if err != nil {
1033				return 0, false
1034			}
1035		}
1036	
1037		return int((float64(hours*3600+minutes*60) + seconds) * 1000), true
1038	}
