45	// NormalizeChannelURL canonicalizes a channel or playlist URL to the form yt-dlp
46	// enumerates cleanly. Channel handles and the /shorts and /streams tabs are
47	// rewritten to /videos; playlist URLs keep their list query. Single-video URLs
48	// are rejected so callers route them to single-video ingestion instead.
49	func NormalizeChannelURL(raw string) (string, error) {
50		value := strings.TrimSpace(raw)
51		if value == "" {
52			return "", &Error{Kind: ErrorKindInvalidURL, URL: raw, Message: "channel url is required"}
53		}
54		if !strings.Contains(value, "://") {
55			value = "https://" + value
56		}
57		parsed, err := url.Parse(value)
58		if err != nil || parsed.Host == "" {
59			return "", &Error{Kind: ErrorKindInvalidURL, URL: raw, Message: "invalid channel URL", Err: err}
60		}
61	
62		host := strings.ToLower(parsed.Host)
63		if host == "youtu.be" || host == "www.youtu.be" {
64			return "", videoURLNotAllowed(raw)
65		}
66		if !strings.Contains(host, "youtube.com") {
67			return "", &Error{
68				Kind:    ErrorKindInvalidURL,
69				URL:     raw,
70				Message: fmt.Sprintf("expected a youtube.com channel or playlist URL: %q", raw),
71			}
72		}
73	
74		path := strings.TrimRight(parsed.Path, "/")
75		if path == "/watch" || strings.TrimSpace(parsed.Query().Get("v")) != "" {
76			return "", videoURLNotAllowed(raw)
77		}
78	
79		if listID := strings.TrimSpace(parsed.Query().Get("list")); listID != "" {
80			normalized := url.URL{Scheme: schemeOrHTTPS(parsed.Scheme), Host: parsed.Host, Path: "/playlist", RawQuery: "list=" + listID}
81			return normalized.String(), nil
82		}
83	
84		if path == "" {
85			return "", &Error{Kind: ErrorKindInvalidURL, URL: raw, Message: "channel URL path is required"}
86		}
87	
88		var normalizedPath string
89		switch {
90		case strings.HasSuffix(path, "/videos"):
91			normalizedPath = path
92		case strings.HasSuffix(path, "/shorts"), strings.HasSuffix(path, "/streams"):
93			normalizedPath = path[:strings.LastIndex(path, "/")] + "/videos"
94		default:
95			normalizedPath = path + "/videos"
96		}
97	
98		normalized := url.URL{Scheme: schemeOrHTTPS(parsed.Scheme), Host: parsed.Host, Path: normalizedPath}
99		return normalized.String(), nil
100	}
