169	// BulkExtract extracts transcripts for the supplied videos using a bounded worker
170	// pool with an inter-request throttle and adaptive backoff on YouTube rate limits.
171	// sink is invoked exactly once per video (serialized, so it need not be
172	// thread-safe) so callers can persist incrementally. It returns the context error
173	// if the run was canceled.
174	func (extractor *Extractor) BulkExtract(
175		ctx context.Context,
176		videos []ChannelVideo,
177		options BulkOptions,
178		sink func(VideoOutcome),
179	) error {
180		if extractor == nil {
181			return errors.New("youtube bulk: extractor is nil")
182		}
183		if sink == nil {
184			return errors.New("youtube bulk: sink is required")
185		}
186		if ctx == nil {
187			ctx = context.Background()
188		}
189		if len(videos) == 0 {
190			return nil
191		}
192	
193		concurrency := max(options.Concurrency, 1)
194		maxRetries := max(options.MaxRetries, 1)
195		backoffMax := options.BackoffMax
196		if backoffMax <= 0 {
197			backoffMax = 60 * time.Second
198		}
199		throttle := max(options.Throttle, 0)
200	
201		extractOptions := ExtractOptions{
202			TranscriptionPolicy:     options.TranscriptionPolicy,
203			PreferredLanguages:      options.PreferredLanguages,
204			AllowTranslatedCaptions: options.AllowTranslatedCaptions,
205		}
206		pacer := &bulkPacer{throttle: throttle, backoffMax: backoffMax}
207	
208		var sinkMu sync.Mutex
209		emit := func(outcome VideoOutcome) {
210			sinkMu.Lock()
211			defer sinkMu.Unlock()
212			sink(outcome)
213		}
214	
215		jobs := make(chan ChannelVideo)
216		var wg sync.WaitGroup
217		for range concurrency {
218			wg.Add(1)
219			go func() {
220				defer wg.Done()
221				for video := range jobs {
222					if ctx.Err() != nil {
223						emit(VideoOutcome{Video: video, Err: ctx.Err()})
224						continue
225					}
226					emit(extractor.extractOneVideo(ctx, video, extractOptions, pacer, maxRetries))
227				}
228			}()
229		}
230	
231	feed:
232		for _, video := range videos {
233			select {
234			case jobs <- video:
235			case <-ctx.Done():
236				break feed
237			}
238		}
239		close(jobs)
240		wg.Wait()
241	
242		return ctx.Err()
243	}
