245	func (extractor *Extractor) extractOneVideo(
246		ctx context.Context,
247		video ChannelVideo,
248		options ExtractOptions,
249		pacer *bulkPacer,
250		maxRetries int,
251	) VideoOutcome {
252		extract := extractor.extractFn
253		if extract == nil {
254			extract = extractor.Extract
255		}
256	
257		var lastErr error
258		for attempt := 1; attempt <= maxRetries; attempt++ {
259			if err := pacer.wait(ctx); err != nil {
260				return VideoOutcome{Video: video, Err: err}
261			}
262	
263			result, err := extract(ctx, video.URL, options)
264			if err == nil {
265				pacer.onSuccess()
266				return VideoOutcome{Video: video, Result: result}
267			}
268	
269			lastErr = err
270			if mediadl.IsContextError(err) {
271				return VideoOutcome{Video: video, Err: err}
272			}
273			if isNetworkBlocked(err) && attempt < maxRetries {
274				pacer.onBlocked()
275				continue
276			}
277			break
278		}
279		return VideoOutcome{Video: video, Err: lastErr}
280	}
