282	// bulkPacer spreads requests across workers with a base throttle plus jitter and
283	// raises a shared exponential penalty when YouTube starts blocking requests.
284	type bulkPacer struct {
285		throttle   time.Duration
286		backoffMax time.Duration
287	
288		mu      sync.Mutex
289		penalty time.Duration
290	}
291	
292	func (pacer *bulkPacer) wait(ctx context.Context) error {
293		pacer.mu.Lock()
294		delay := pacer.penalty
295		pacer.mu.Unlock()
296	
297		if pacer.throttle > 0 {
298			jitter := time.Duration(rand.Int63n(int64(pacer.throttle/2) + 1))
299			delay += pacer.throttle + jitter
300		}
301		return bulkSleep(ctx, delay)
302	}
303	
304	func (pacer *bulkPacer) onBlocked() {
305		pacer.mu.Lock()
306		defer pacer.mu.Unlock()
307		if pacer.penalty <= 0 {
308			base := pacer.throttle
309			if base <= 0 {
310				base = time.Second
311			}
312			pacer.penalty = base
313		} else {
314			pacer.penalty *= 2
315		}
316		if pacer.penalty > pacer.backoffMax {
317			pacer.penalty = pacer.backoffMax
318		}
