3146	+	var selected fs.DirEntry
3147	+	selectedExt := ""
3148	+	for _, ext := range []string{".json3", ".vtt"} {
3149	+		for _, entry := range entries {
3150	+			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ext) {
3151	+				continue
3152	+			}
3153	+			selected = entry
3154	+			selectedExt = ext
3155	+			break
3156	+		}
3157	+		if selected != nil {
3158	+			break
3159	+		}
3160	+	}
3161	+	if selected == nil {
3162	+		return nil, "", fmt.Errorf("yt-dlp captions: no supported caption file was written")
3163	+	}
3164	+
3165	+	path := filepath.Join(dir, selected.Name())
3166	+	data, err := os.ReadFile(path)
3167	+	if err != nil {
