3173	+func formatYTDLPJSON3Transcript(data []byte) (string, error) {
3174	+	var payload struct {
3175	+		Events []struct {
3176	+			StartMs  int `json:"tStartMs"`
3177	+			Segments []struct {
3178	+				Text string `json:"utf8"`
3179	+			} `json:"segs"`
3180	+		} `json:"events"`
3181	+	}
3182	+	if err := json.Unmarshal(data, &payload); err != nil {
3183	+		return "", fmt.Errorf("yt-dlp captions: parse json3: %w", err)
3184	+	}
3185	+
3186	+	transcript := make([]transcriptSegment, 0, len(payload.Events))
3187	+	for _, event := range payload.Events {
3188	+		if len(event.Segments) == 0 {
3189	+			continue
3190	+		}
3191	+		var builder strings.Builder
3192	+		for _, segment := range event.Segments {
3193	+			builder.WriteString(segment.Text)
3194	+		}
3195	+		text := normalizeTranscriptText(builder.String())
3196	+		if text == "" {
3197	+			continue
3198	+		}
3199	+		transcript = append(transcript, transcriptSegment{
3200	+			StartMs: event.StartMs,
3201	+			Text:    text,
3202	+		})
3203	+	}
3204	+	return formatTranscriptMarkdown(transcript), nil
3205	+}
