3207	+func formatYTDLPVTTTranscript(data []byte) (string, error) {
3208	+	lines := strings.Split(string(data), "\n")
3209	+	transcript := make([]transcriptSegment, 0, len(lines)/3)
3210	+	for index := 0; index < len(lines); index++ {
3211	+		line := strings.TrimSpace(strings.TrimPrefix(lines[index], "\ufeff"))
3212	+		if !strings.Contains(line, "-->") {
3213	+			continue
3214	+		}
3215	+		startText, _, _ := strings.Cut(line, "-->")
3216	+		startMs, ok := parseVTTTimestampMs(startText)
3217	+		if !ok {
3218	+			continue
3219	+		}
3220	+		textLines := make([]string, 0, 2)
3221	+		for index++; index < len(lines); index++ {
3222	+			textLine := strings.TrimSpace(lines[index])
3223	+			if textLine == "" {
3224	+				break
3225	+			}
3226	+			textLines = append(textLines, textLine)
3227	+		}
3228	+		text := normalizeTranscriptText(strings.Join(textLines, " "))
3229	+		if text == "" {
3230	+			continue
3231	+		}
3232	+		transcript = append(transcript, transcriptSegment{StartMs: startMs, Text: text})
3233	+	}
3234	+	return formatTranscriptMarkdown(transcript), nil
3235	+}
3236	+
3237	+func parseVTTTimestampMs(value string) (int, bool) {
3238	+	value = strings.TrimSpace(value)
3239	+	parts := strings.Split(value, ":")
3240	+	if len(parts) < 2 || len(parts) > 3 {
3241	+		return 0, false
3242	+	}
3243	+
3244	+	secondsPart := parts[len(parts)-1]
3245	+	seconds, err := strconv.ParseFloat(strings.Replace(secondsPart, ",", ".", 1), 64)
3246	+	if err != nil {
3247	+		return 0, false
3248	+	}
3249	+	minutes, err := strconv.Atoi(parts[len(parts)-2])
3250	+	if err != nil {
3251	+		return 0, false
3252	+	}
3253	+	hours := 0
3254	+	if len(parts) == 3 {
3255	+		hours, err = strconv.Atoi(parts[0])
3256	+		if err != nil {
3257	+			return 0, false
3258	+		}
3259	+	}
3260	+
3261	+	return int((float64(hours*3600+minutes*60) + seconds) * 1000), true
3262	+}
