4327	+// videos, deduplicates by ID, and synthesizes watch URLs when needed.
4328	+func channelVideosFromEntries(entries []mediadl.PlaylistEntry) []ChannelVideo {
4329	+	videos := make([]ChannelVideo, 0, len(entries))
4330	+	seen := make(map[string]struct{}, len(entries))
4331	+	for _, entry := range entries {
4332	+		id := strings.TrimSpace(entry.ID)
4333	+		if !youtubeVideoIDPattern.MatchString(id) {
4334	+			continue
4335	+		}
4336	+		if _, ok := seen[id]; ok {
4337	+			continue
4338	+		}
4339	+		seen[id] = struct{}{}
4340	+
4341	+		videoURL := strings.TrimSpace(entry.WebpageURL)
4342	+		if videoURL == "" {
4343	+			videoURL = strings.TrimSpace(entry.URL)
4344	+		}
4345	+		if !strings.HasPrefix(strings.ToLower(videoURL), "http") {
4346	+			videoURL = "https://www.youtube.com/watch?v=" + id
4347	+		}
4348	+
4349	+		videos = append(videos, ChannelVideo{
4350	+			VideoID: id,
4351	+			Title:   strings.TrimSpace(entry.Title),
4352	+			URL:     videoURL,
4353	+		})
4354	+	}
4355	+	return videos
4356	+}
4357	+
4358	+// BulkExtract extracts transcripts for the supplied videos using a bounded worker
4359	+// pool with an inter-request throttle and adaptive backoff on YouTube rate limits.
4360	+// sink is invoked exactly once per video (serialized, so it need not be
4361	+// thread-safe) so callers can persist incrementally. It returns the context error
4362	+// if the run was canceled.
4363	+func (extractor *Extractor) BulkExtract(
4364	+	ctx context.Context,
4365	+	videos []ChannelVideo,
4366	+	options BulkOptions,
4367	+	sink func(VideoOutcome),
4368	+) error {
4369	+	if extractor == nil {
4370	+		return errors.New("youtube bulk: extractor is nil")
4371	+	}
4372	+	if sink == nil {
4373	+		return errors.New("youtube bulk: sink is required")
4374	+	}
4375	+	if ctx == nil {
4376	+		ctx = context.Background()
4377	+	}
4378	+	if len(videos) == 0 {
4379	+		return nil
4380	+	}
4381	+
4382	+	concurrency := max(options.Concurrency, 1)
4383	+	maxRetries := max(options.MaxRetries, 1)
4384	+	backoffMax := options.BackoffMax
4385	+	if backoffMax <= 0 {
4386	+		backoffMax = 60 * time.Second
4387	+	}
4388	+	throttle := max(options.Throttle, 0)
4389	+
4390	+	extractOptions := ExtractOptions{
4391	+		TranscriptionPolicy:     options.TranscriptionPolicy,
4392	+		PreferredLanguages:      options.PreferredLanguages,
4393	+		AllowTranslatedCaptions: options.AllowTranslatedCaptions,
4394	+	}
4395	+	pacer := &bulkPacer{throttle: throttle, backoffMax: backoffMax}
4396	+
4397	+	var sinkMu sync.Mutex
4398	+	emit := func(outcome VideoOutcome) {
4399	+		sinkMu.Lock()
4400	+		defer sinkMu.Unlock()
4401	+		sink(outcome)
4402	+	}
4403	+
4404	+	jobs := make(chan ChannelVideo)
4405	+	var wg sync.WaitGroup
4406	+	for range concurrency {
4407	+		wg.Add(1)
4408	+		go func() {
4409	+			defer wg.Done()
4410	+			for video := range jobs {
4411	+				if ctx.Err() != nil {
4412	+					emit(VideoOutcome{Video: video, Err: ctx.Err()})
4413	+					continue
4414	+				}
4415	+				emit(extractor.extractOneVideo(ctx, video, extractOptions, pacer, maxRetries))
4416	+			}
4417	+		}()
4418	+	}
4419	+
4420	+feed:
4421	+	for _, video := range videos {
4422	+		select {
4423	+		case jobs <- video:
4424	+		case <-ctx.Done():
4425	+			break feed
4426	+		}
4427	+	}
4428	+	close(jobs)
4429	+	wg.Wait()
4430	+
4431	+	return ctx.Err()
4432	+}
4433	+
4434	+func (extractor *Extractor) extractOneVideo(
4435	+	ctx context.Context,
4436	+	video ChannelVideo,
4437	+	options ExtractOptions,
4438	+	pacer *bulkPacer,
4439	+	maxRetries int,
4440	+) VideoOutcome {
4441	+	extract := extractor.extractFn
4442	+	if extract == nil {
4443	+		extract = extractor.Extract
4444	+	}
4445	+
4446	+	var lastErr error
4447	+	for attempt := 1; attempt <= maxRetries; attempt++ {
4448	+		if err := pacer.wait(ctx); err != nil {
4449	+			return VideoOutcome{Video: video, Err: err}
4450	+		}
4451	+
4452	+		result, err := extract(ctx, video.URL, options)
4453	+		if err == nil {
4454	+			pacer.onSuccess()
4455	+			return VideoOutcome{Video: video, Result: result}
4456	+		}
4457	+
4458	+		lastErr = err
4459	+		if mediadl.IsContextError(err) {
4460	+			return VideoOutcome{Video: video, Err: err}
4461	+		}
4462	+		if isNetworkBlocked(err) && attempt < maxRetries {
4463	+			pacer.onBlocked()
4464	+			continue
4465	+		}
4466	+		break
4467	+	}
4468	+	return VideoOutcome{Video: video, Err: lastErr}
4469	+}
4470	+
4471	+// bulkPacer spreads requests across workers with a base throttle plus jitter and
4472	+// raises a shared exponential penalty when YouTube starts blocking requests.
4473	+type bulkPacer struct {
4474	+	throttle   time.Duration
4475	+	backoffMax time.Duration
4476	+
4477	+	mu      sync.Mutex
4478	+	penalty time.Duration
4479	+}
4480	+
4481	+func (pacer *bulkPacer) wait(ctx context.Context) error {
4482	+	pacer.mu.Lock()
4483	+	delay := pacer.penalty
4484	+	pacer.mu.Unlock()
4485	+
4486	+	if pacer.throttle > 0 {
4487	+		jitter := time.Duration(rand.Int63n(int64(pacer.throttle/2) + 1))
4488	+		delay += pacer.throttle + jitter
4489	+	}
4490	+	return bulkSleep(ctx, delay)
4491	+}
4492	+
4493	+func (pacer *bulkPacer) onBlocked() {
4494	+	pacer.mu.Lock()
4495	+	defer pacer.mu.Unlock()
4496	+	if pacer.penalty <= 0 {
4497	+		base := pacer.throttle
4498	+		if base <= 0 {
4499	+			base = time.Second
4500	+		}
4501	+		pacer.penalty = base
4502	+	} else {
4503	+		pacer.penalty *= 2
4504	+	}
4505	+	if pacer.penalty > pacer.backoffMax {
4506	+		pacer.penalty = pacer.backoffMax
4507	+	}
4508	+}
4509	+
4510	+func (pacer *bulkPacer) onSuccess() {
4511	+	pacer.mu.Lock()
4512	+	defer pacer.mu.Unlock()
4513	+	pacer.penalty /= 2
4514	+	if pacer.penalty < 0 {
4515	+		pacer.penalty = 0
4516	+	}
4517	+}
4518	+
4519	+func bulkSleep(ctx context.Context, delay time.Duration) error {
4520	+	if delay <= 0 {
4521	+		return ctx.Err()
4522	+	}
4523	+	timer := time.NewTimer(delay)
4524	+	defer timer.Stop()
4525	+	select {
4526	+	case <-ctx.Done():
4527	+		return ctx.Err()
4528	+	case <-timer.C:
4529	+		return nil
4530	+	}
4531	+}
4532	+
4533	+func isNetworkBlocked(err error) bool {
4534	+	return mediadl.IsNetworkBlocked(err) || mediadl.IsRateLimited(err)
4535	+}
